const quotationSubjectMatchesRequest = (
  request: CurrentPricingDecisionRequest,
  binding: PricingQuotationBinding,
): boolean => {
  if (
    binding.subject.purchaseContext.contextRef !== request.decision.purchasingContext.contextRef ||
    binding.subject.purchaseContext.contextRevision !== request.decision.purchasingContext.contextRevision
  ) {
    return false;
  }
  if (request.subject.kind === 'GUEST') {
    return (
      binding.subject.kind === 'GUEST' &&
      binding.subject.guestEvidenceRef === request.subject.guestEvidenceRef &&
      binding.subject.guestSessionRef === request.subject.guestSessionRef
    );
  }
  return (
    binding.subject.kind === 'AUTHENTICATED' &&
    binding.subject.subjectRef.moduleId === request.subject.profileRef.moduleId &&
    binding.subject.subjectRef.resourceId === request.subject.profileRef.resourceId &&
    binding.subject.subjectRef.resourceType === request.subject.profileRef.resourceType &&
    binding.subject.subjectRef.tenantId === request.subject.profileRef.tenantId
  );
};

